/**
 * accessories-products.js
 * Danh sách dữ liệu sản phẩm cho trang Accessories & Equipment (PLP).
 * Dữ liệu được tổng hợp đầy đủ từ toàn bộ danh mục Accessories & Equipment - Nike VN
 * (toàn bộ sản phẩm trong file PDF nguồn), đã được phân loại theo các bộ filter:
 * Category (Bags & Backpacks, Balls, Gloves and Mitts, Hats/Visors & Headbands,
 * Pads/Guards & Protection, Socks), Gender, Color, Brand, Sports, Features, Technology.
 *
 * Trường dữ liệu:
 *  - id            : mã định danh duy nhất
 *  - name          : tên sản phẩm
 *  - type          : loại / mô tả ngắn (hiển thị dưới tên, ví dụ "Backpack (25L)")
 *  - price         : giá (số nguyên, đơn vị VNĐ)
 *  - img           : ảnh đại diện (dùng cho PLP card + ảnh chính PDP)
 *  - images        : (optional) danh sách ảnh phụ dùng cho thumbnail ở trang chi tiết
 *  - badge         : nhãn hiển thị phía trên tên SP ("Recycled Materials" | "Bestseller"
 *                     | "Promo Exclusion" | "" nếu không có)
 *  - recycled      : true nếu sản phẩm dùng vật liệu tái chế -> hiện badge "Recycled Materials"
 *                    + khối "How This Was Made" ở trang chi tiết
 *  - gender        : "men" | "women" | "unisex"
 *  - category      : "bags-backpacks" | "balls" | "gloves-mitts" | "hats-visors-headbands"
 *                     | "pads-guards-protection" | "socks"
 *  - colors        : mảng slug màu, dùng để filter theo Color
 *  - brand         : slug brand, dùng để filter theo Brand ("nike" | "nike-sportswear" | "jordan" | "acg")
 *  - sport          : mảng slug sport, dùng để filter theo Sports
 *  - features      : mảng slug feature, dùng để filter theo Features
 *  - technology    : mảng slug technology, dùng để filter theo Technology
 *  - sizes         : mảng size hiển thị ở PDP. ["One Size"] nếu không phân size
 *  - colorName     : tên màu đầy đủ hiển thị trong specs
 *  - styleCode     : mã style
 *  - origin        : nơi sản xuất
 *  - description   : mô tả sản phẩm
 *
 * Lưu ý: ảnh (img) dùng placeholder (placehold.co) vì PDF nguồn không export ra ảnh sản phẩm thật,
 * màu sắc / styleCode / origin / mô tả được suy luận hợp lý dựa trên tên & loại sản phẩm vì PDF
 * gốc chỉ liệt kê tên, loại, giá và badge (không có thông số chi tiết).
 */

